definition.script:
node {
    stage('Retrieve secret') {
        withCredentials([conjurSecretCredential(credentialsId: 'folder-job-credential1', variable: 'CONJUR_SECRET')]) {
                sh '''#!/bin/bash

                # Echo the CONJUR_SECRET value
                echo "CONJUR_SECRET: $CONJUR_SECRET"

                # Check if the CONJUR_SECRET value
                if [ "$CONJUR_SECRET" == "folder1" ]; then
                echo "Secret retrieved successfully"
                else
                echo "Unable to retrieve the secret"
                exit 1
                fi
                '''
        }
   }
}
